INSERT INTO DimCustomer (SK_CustomerID, CustomerID, TaxID, Status, LastName, FirstName, MiddleInitial, Gender, Tier, DOB, AddressLine1, AddressLine2, PostalCode, City, StateProv, Country, Phone1, Phone2, Phone3, Email1, Email2, NationalTaxRateDesc, NationalTaxRate, LocalTaxRateDesc, LocalTaxRate, AgencyID, CreditRating, NetWorth, MarketingNameplate, IsCurrent, BatchID, EffectiveDate, EndDate) WITH history AS (SELECT customerid, CASE WHEN actiontype = 'INACT' THEN 'INAC' ELSE 'ACTV' END AS status_id, LAST_VALUE(taxid IGNORE NULLS) OVER w AS taxid, LAST_VALUE(lastname IGNORE NULLS) OVER w AS lastname, LAST_VALUE(firstname IGNORE NULLS) OVER w AS firstname, LAST_VALUE(middleinitial IGNORE NULLS) OVER w AS middleinitial, LAST_VALUE(gender IGNORE NULLS) OVER w AS gender, LAST_VALUE(tier IGNORE NULLS) OVER w AS tier, LAST_VALUE(dob IGNORE NULLS) OVER w AS dob, LAST_VALUE(addressline1 IGNORE NULLS) OVER w AS addressline1, LAST_VALUE(addressline2 IGNORE NULLS) OVER w AS addressline2, LAST_VALUE(postalcode IGNORE NULLS) OVER w AS postalcode, LAST_VALUE(city IGNORE NULLS) OVER w AS city, LAST_VALUE(stateprov IGNORE NULLS) OVER w AS stateprov, LAST_VALUE(country IGNORE NULLS) OVER w AS country, LAST_VALUE(phone1 IGNORE NULLS) OVER w AS phone1, LAST_VALUE(phone2 IGNORE NULLS) OVER w AS phone2, LAST_VALUE(phone3 IGNORE NULLS) OVER w AS phone3, LAST_VALUE(email1 IGNORE NULLS) OVER w AS email1, LAST_VALUE(email2 IGNORE NULLS) OVER w AS email2, LAST_VALUE(lcl_tx_id IGNORE NULLS) OVER w AS lcl_tx_id, LAST_VALUE(nat_tx_id IGNORE NULLS) OVER w AS nat_tx_id, CAST(update_ts AS DATE) AS effectivedate, COALESCE(LEAD(CAST(update_ts AS DATE)) OVER (PARTITION BY customerid ORDER BY update_ts), CAST('9999-12-31' AS DATE)) AS enddate FROM CustomerMgmtRaw WHERE actiontype IN ('NEW', 'UPDCUST', 'INACT') WINDOW w AS (PARTITION BY customerid ORDER BY update_ts ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT CAST(STRFTIME(h.effectivedate, '%Y%m%d') || CAST(h.customerid AS TEXT) AS BIGINT), h.customerid, h.taxid, st.ST_NAME, h.lastname, h.firstname, h.middleinitial, CASE WHEN UPPER(h.gender) IN ('M', 'F') THEN UPPER(h.gender) ELSE 'U' END, h.tier, h.dob, h.addressline1, h.addressline2, h.postalcode, h.city, h.stateprov, h.country, h.phone1, h.phone2, h.phone3, h.email1, h.email2, nat.TX_NAME, nat.TX_RATE, lcl.TX_NAME, lcl.TX_RATE, p.agencyid, p.creditrating, p.networth, p.marketingnameplate, h.enddate = CAST('9999-12-31' AS DATE), 1, h.effectivedate, h.enddate FROM history AS h JOIN StatusType AS st ON st.ST_ID = h.status_id LEFT JOIN TaxRate AS nat ON nat.TX_ID = h.nat_tx_id LEFT JOIN TaxRate AS lcl ON lcl.TX_ID = h.lcl_tx_id LEFT JOIN ProspectRaw AS p ON p.batchid = 1 AND UPPER(p.lastname) = UPPER(h.lastname) AND UPPER(p.firstname) = UPPER(h.firstname) AND UPPER(p.addressline1) = UPPER(h.addressline1) AND UPPER(COALESCE(p.addressline2, '')) = UPPER(COALESCE(h.addressline2, '')) AND UPPER(p.postalcode) = UPPER(h.postalcode) WHERE h.effectivedate < h.enddate

